#include "fuse/identity.h"
#pragma comment(lib,"ncrypt.lib")
namespace fuse {
Status identity_open_or_create(SigningIdentity*out,const std::wstring&name){if(!out)return Status::InvalidArgument;*out=SigningIdentity{};out->key_name=name;auto attempt=[&](const wchar_t*provider,bool lower)->Status{NCRYPT_PROV_HANDLE ph=0;if(NCryptOpenStorageProvider(&ph,provider,0)!=ERROR_SUCCESS)return Status::IdentityError;NCRYPT_KEY_HANDLE kh=0;if(NCryptOpenKey(ph,&kh,name.c_str(),0,NCRYPT_SILENT_FLAG)==ERROR_SUCCESS){out->provider=ph;out->key=kh;out->software_fallback=lower;return Status::Ok;}if(NCryptCreatePersistedKey(ph,&kh,NCRYPT_ECDSA_P256_ALGORITHM,name.c_str(),0,0)==ERROR_SUCCESS){DWORD usage=NCRYPT_ALLOW_SIGNING_FLAG;NCryptSetProperty(kh,NCRYPT_KEY_USAGE_PROPERTY,(PBYTE)&usage,sizeof(usage),0);if(NCryptFinalizeKey(kh,0)==ERROR_SUCCESS){out->provider=ph;out->key=kh;out->software_fallback=lower;return Status::Ok;}NCryptDeleteKey(kh,0);}NCryptFreeObject(ph);return Status::IdentityError;};if(attempt(MS_PLATFORM_CRYPTO_PROVIDER,false)==Status::Ok)return Status::Ok;return attempt(MS_KEY_STORAGE_PROVIDER,true);}
void identity_close(SigningIdentity*i){if(!i)return;if(i->key)NCryptFreeObject(i->key);if(i->provider)NCryptFreeObject(i->provider);*i=SigningIdentity{};}
Status identity_sign(SigningIdentity*i,const Digest256*d,Buffer*out){if(!i||!i->key||!d||!out)return Status::InvalidArgument;DWORD n=0;if(NCryptSignHash(i->key,nullptr,(PBYTE)d->bytes.data(),32,nullptr,0,&n,0)!=ERROR_SUCCESS)return Status::IdentityError;out->resize(n);DWORD got=0;if(NCryptSignHash(i->key,nullptr,(PBYTE)d->bytes.data(),32,out->data(),n,&got,0)!=ERROR_SUCCESS)return Status::IdentityError;out->resize(got);return Status::Ok;}
Status identity_verify(SigningIdentity*i,const Digest256*d,ByteSpan sig){if(!i||!i->key)return Status::InvalidArgument;return NCryptVerifySignature(i->key,nullptr,(PBYTE)d->bytes.data(),32,(PBYTE)sig.data,(DWORD)sig.size,0)==ERROR_SUCCESS?Status::Ok:Status::IdentityError;}
}
